const fs = require('fs');
const path = require('path');

async function listTables() {
  const projectId = process.env.PARAGON_PROJECT_ID;
  const userToken = process.env.PARAGON_USER_TOKEN;

  if (!projectId || !userToken) {
    console.error('Missing PARAGON_PROJECT_ID or PARAGON_USER_TOKEN environment variables');
    process.exit(1);
  }

  const url = `https://proxy.useparagon.com/projects/${projectId}/sdk/proxy/postgresql`;
  const query = "SELECT table_name FROM information_schema.tables WHERE table_schema = 'public';";

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${userToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ query })
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Proxy API request failed: ${response.status} ${response.statusText} - ${errorText}`);
    }

    const data = await response.json();
    const outputPath = path.join(__dirname, 'tables.json');
    fs.writeFileSync(outputPath, JSON.stringify(data, null, 2));
    console.log(`Tables listed and saved to ${outputPath}`);
  } catch (error) {
    console.error('Error listing tables:', error.message);
    process.exit(1);
  }
}

listTables();

